    basePoints.push(i * sin(TWO_PI / 3) + random(-0.1, 0.1));
  }
  points.push(...basePoints);

  for (let i = 0; i < recursiveDepth; i++) {
    const childPoints = [];
    for (let j = 0; j < points.length; j += 2) {
      const p1 = points[j];
      const p2 = points[j + 1];
      childPoints.push((p1 + p2) / 2);
